import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    D = int(data[0])
    A = int(data[1])
    N = int(data[2])

    nights = 32 - N
    if N <= 15:
        rate = D + (N - 1) * A
    else:
        rate = D + 14 * A

    print(nights * rate)

if __name__ == "__main__":
    main()
